from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        # clean up expired entry for this key if present
        if key in cache and is_expired(key, t):
            del cache[key]

        if kind == 'put':
            value = op[3]
            if key in cache:
                # update existing, refresh write time, move to MRU
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    # evict LRU
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        elif kind == 'get':
            if key in cache:
                value, wt = cache[key]
                results.append(value)
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

